SELECT F.FACTORCONVERSION, D.*
FROM DATOS_P_STOCK D INNER JOIN P_FACTORCONV F ON D.CODIGO = F.PRODUCTO AND D.UNIDADMEDIDA = F.UNIDADSUPERIOR 

select * 
from P_FACTORCONV where PRODUCTO in (SELECT distinct codigo
FROM DATOS_P_STOCK)

SELECT distinct codigo
FROM DATOS_P_STOCK 

